/**
 * The Gentlemen's Invitational — League Hub
 * Renders everything from LEAGUE_DATA (data.js, generated by sync_data.py).
 */

const D = LEAGUE_DATA;
const CS = D.currentSeason;
const TOTAL_GW = 38;

const PAGES = [
  { id: "home", label: "Home" },
  { id: "table", label: "Table" },
  { id: "matches", label: "Matches" },
  { id: "cups", label: "Cups" },
  { id: "managers", label: "Managers" },
  { id: "history", label: "History" },
  { id: "rules", label: "Rules & Prizes" },
];

const CREST_COLORS = [
  "#e5484d", "#3e63dd", "#30a46c", "#f76b15", "#8e4ec6", "#12a594", "#d6409f",
  "#0090ff", "#ad7f58", "#5b5bd6", "#c2a000", "#46a758", "#e54666", "#6e56cf",
];

const ICON = {
  chevron: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9l6 6 6-6"/></svg>`,
  arrow: `<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg>`,
  left: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M15 6l-6 6 6 6"/></svg>`,
  right: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 6l6 6-6 6"/></svg>`,
  close: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg>`,
  search: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg>`,
  sun: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg>`,
  moon: `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.8A9 9 0 1111.2 3a7 7 0 009.8 9.8z"/></svg>`,
};

/* ---------- Helpers ---------- */

const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];

function esc(v) {
  return String(v ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}
const fmt = (n, d = 0) => Number(n ?? 0).toLocaleString("en-US", { minimumFractionDigits: d, maximumFractionDigits: d });
const fmtPts = n => fmt(n, Number.isInteger(+n) ? 0 : 2);
const money = n => "$" + fmt(n);
// Formats an ISO timestamp as "Thu, Oct 22" in league time.
function fmtDate(iso) {
  if (!iso) return "";
  return new Date(iso).toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric", timeZone: "America/New_York" });
}
// "Tue, Oct 20, 3:00 PM ET"
function fmtDateTime(iso) {
  if (!iso) return "";
  return new Date(iso).toLocaleString("en-US", { weekday: "short", month: "short", day: "numeric", hour: "numeric", minute: "2-digit", timeZone: "America/New_York" }) + " ET";
}
const ordinal = n => n + (["th", "st", "nd", "rd"][(n % 100 - 20) % 10] || ["th", "st", "nd", "rd"][n % 100] || "th");

const managerById = Object.fromEntries(D.managers.map((m, i) => [m.id, { ...m, color: CREST_COLORS[i % CREST_COLORS.length] }]));
const managerByName = Object.fromEntries(Object.values(managerById).map(m => [m.name, m]));
const standingById = Object.fromEntries(CS.standings.map(s => [s.managerId, s]));

function findManager(name) {
  if (!name) return null;
  if (managerByName[name]) return managerByName[name];
  const first = String(name).split(" ")[0].toLowerCase();
  return Object.values(managerById).find(m => m.name.split(" ")[0].toLowerCase() === first) || null;
}

function crest(nameOrMgr, size = "") {
  const m = typeof nameOrMgr === "string" ? findManager(nameOrMgr) : nameOrMgr;
  const label = m ? m.shortName : String(nameOrMgr || "?").replace(/[^A-Za-z]/g, "").slice(0, 3).toUpperCase();
  const color = m ? m.color : "#5c6878";
  return `<span class="crest ${size}" style="--c:${color}" aria-hidden="true">${esc(label)}</span>`;
}

function clubCell(name, team, { link = true, size = "" } = {}) {
  const m = findManager(name);
  const inner = `${crest(m || name, size)}<span class="club-text"><span class="club-name">${esc(team || (m && m.teamName) || name)}</span><span class="club-mgr">${esc(name)}</span></span>`;
  if (link && m) return `<button class="club-btn club" data-mgr="${m.id}">${inner}</button>`;
  return `<span class="club">${inner}</span>`;
}

function formPills(form = [], len = 5) {
  const items = form.slice(-len);
  const pad = Array(Math.max(0, len - items.length)).fill("");
  return `<span class="form" aria-label="Form: ${items.join(" ") || "none"}">${items.map(r => `<span class="f-pill f-${esc(r)}">${esc(r)}</span>`).join("")}${pad.map(() => `<span class="f-pill f-empty">–</span>`).join("")}</span>`;
}

function delta(n, str) {
  const v = Number(n);
  if (!v) return `<span class="delta-flat">${esc(str ?? "–")}</span>`;
  return `<span class="${v > 0 ? "delta-up" : "delta-down"}">${v > 0 ? "▲" : "▼"} ${esc(str ?? Math.abs(v))}</span>`;
}

function segmented(name, options, active) {
  return `<div class="segmented" role="tablist" data-seg="${name}">${options.map(o =>
    `<button class="seg-btn" role="tab" data-val="${o.id}" aria-selected="${o.id === active}">${esc(o.label)}</button>`).join("")}</div>`;
}

function cardHead(title, sub = "", right = "") {
  return `<div class="card-head"><div><h3 class="card-title">${esc(title)}</h3>${sub ? `<p class="card-sub">${esc(sub)}</p>` : ""}</div>${right}</div>`;
}

function pageHead(id, eyebrow, title, sub, right = "") {
  return `<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1 class="page-title display" id="t-${id}">${esc(title)}</h1>${sub ? `<p class="page-sub">${esc(sub)}</p>` : ""}</div>${right}</div>`;
}

function tipAttr(html) {
  return `data-tip="${esc(html)}"`;
}

/* ---------- Season state ---------- */

const completed = (CS.completedGameweeks || []).map(Number);
const lastCompleted = completed.length ? Math.max(...completed) : 0;
const liveGw = CS.liveGameweek ?? null;

// The home page features a gameweek until its switch time (the first 9 AM ET after it officially ends,
// 8h after its last kickoff; both set by sync_data.py), then moves on to the next.
const gwDates = CS.gameweekDates || {};
const rolloverAt = gw => gwDates[gw] ? new Date(gwDates[gw].switch || gwDates[gw].end).getTime() : null;

function featuredGameweek(now = Date.now()) {
  for (let gw = 1; gw <= TOTAL_GW; gw++) {
    const at = rolloverAt(gw);
    if (at !== null && now < at) return gw;
  }
  return Object.keys(gwDates).length ? TOTAL_GW : Math.max(1, lastCompleted);
}

const currentGw = featuredGameweek();
const nextGw = Math.min(TOTAL_GW, currentGw + 1);
const gwState = gw => completed.includes(gw) ? "final" : gw === liveGw ? "live" : "scheduled";
const clGws = new Set((D.championsLeague.groupSchedule || []).map(g => +g.gw));
const cupGws = new Set();
Object.entries(CS.gameweekMatchups).forEach(([gw, ms]) => {
  ms.forEach(m => {
    if (m.competition === "champions_league") clGws.add(+gw);
    if (m.competition === "lingineni_cup") cupGws.add(+gw);
  });
});

// Tag every fixture with its gameweek so any element can point back to it (see matchAttr).
Object.entries(CS.gameweekMatchups).forEach(([gw, ms]) => ms.forEach(m => (m.gw = +gw)));
const teamIdByName = Object.fromEntries(D.managers.map(m => [m.teamName, m.teamId]));

function matchAttr(m) {
  return `data-match="${m.gw}|${encodeURIComponent(m.homeTeam)}|${encodeURIComponent(m.awayTeam)}|${m.competition}" role="button" tabindex="0" aria-label="${esc(`View lineups: ${m.homeTeam} vs ${m.awayTeam}, gameweek ${m.gw}`)}"`;
}
function findMatch(ref) {
  const [gw, home, away, comp] = ref.split("|");
  return matchesFor(+gw).find(m => m.homeTeam === decodeURIComponent(home) && m.awayTeam === decodeURIComponent(away) && m.competition === comp);
}

function matchesFor(gw) { return CS.gameweekMatchups[gw] || CS.gameweekMatchups[String(gw)] || []; }
function isFinal(m) { return m.status === "Final"; }
function hasScore(m) { return m.status === "Final" || m.status === "Live"; }
const LIVE_LABEL = `<span style="display:inline-flex;align-items:center;gap:6px;color:var(--accent-text)"><span class="live-dot"></span>Live</span>`;
function compMeta(c) {
  if (c === "champions_league") return { label: "Champions League", cls: "cl" };
  if (c === "lingineni_cup") return { label: "Lingineni Cup", cls: "cup" };
  return { label: "Premier League", cls: "" };
}

/* ---------- Sortable table ---------- */

const tableState = {};

function dataTable(key, rows, cols, { rowClass = () => "", defaultSort = null } = {}) {
  const st = tableState[key] || (tableState[key] = defaultSort || { col: null, dir: "desc" });
  let sorted = rows.slice();
  const sc = cols.find(c => c.key === st.col);
  if (sc) {
    const get = sc.sortVal || (r => r[sc.key]);
    sorted.sort((a, b) => {
      const x = get(a), y = get(b);
      const cmp = typeof x === "number" && typeof y === "number" ? x - y : String(x).localeCompare(String(y));
      return st.dir === "asc" ? cmp : -cmp;
    });
  }
  const th = cols.map(c => {
    const sortAttr = c.sortable === false ? "" : ` class="sortable ${c.cls || ""}" data-sort-table="${key}" data-sort-col="${c.key}" tabindex="0"`;
    const aria = st.col === c.key ? ` aria-sort="${st.dir === "asc" ? "ascending" : "descending"}"` : "";
    return `<th${sortAttr || ` class="${c.cls || ""}"`}${aria} title="${esc(c.title || c.label)}">${esc(c.label)}</th>`;
  }).join("");
  const body = sorted.map(r => `<tr class="${rowClass(r)}">${cols.map(c => `<td class="${c.cls || ""}">${c.render ? c.render(r) : esc(r[c.key])}</td>`).join("")}</tr>`).join("");
  return `<div class="table-wrap"><table class="data"><thead><tr>${th}</tr></thead><tbody>${body}</tbody></table></div>`;
}

document.addEventListener("click", e => {
  const th = e.target.closest("[data-sort-table]");
  if (!th) return;
  sortBy(th.dataset.sortTable, th.dataset.sortCol);
});
document.addEventListener("keydown", e => {
  const th = e.target.closest && e.target.closest("[data-sort-table]");
  if (th && (e.key === "Enter" || e.key === " ")) { e.preventDefault(); sortBy(th.dataset.sortTable, th.dataset.sortCol); }
});

function sortBy(key, col) {
  const st = tableState[key] || (tableState[key] = { col: null, dir: "desc" });
  if (st.col === col) st.dir = st.dir === "desc" ? "asc" : "desc";
  else { st.col = col; st.dir = ["rank", "pos", "name", "team", "player", "manager"].includes(col) ? "asc" : "desc"; }
  rerender();
}

/* ---------- Router ---------- */

const state = {
  page: "home",
  sub: {},
  gw: currentGw,
  comp: "all",
  scoringPos: "D",
  sim: {},
  season: Object.keys(D.history.seasons).sort().reverse()[0],
  pancakes: 12,
  bylawQuery: "",
};

function parseHash() {
  const [page, sub] = (location.hash.replace(/^#/, "") || "home").split("/");
  state.page = PAGES.some(p => p.id === page) ? page : "home";
  if (sub) state.sub[state.page] = sub;
}

function go(page, sub) {
  const h = "#" + page + (sub ? "/" + sub : "");
  if (location.hash !== h) location.hash = h;
  else { parseHash(); render(); }
}

function renderNav() {
  const html = PAGES.map(p => `<button class="nav-link" data-go="${p.id}" ${p.id === state.page ? 'aria-current="page"' : ""}>${p.label}</button>`).join("");
  $$("[data-nav]").forEach(n => (n.innerHTML = html));
}

const RENDERERS = {};
function render() {
  renderNav();
  $$(".page").forEach(p => p.classList.toggle("active", p.id === "page-" + state.page));
  rerender();
  window.scrollTo(0, 0);
}
function rerender() {
  const el = $("#page-" + state.page);
  el.innerHTML = RENDERERS[state.page]();
  afterRender[state.page] && afterRender[state.page](el);
}
const afterRender = {};

document.addEventListener("click", e => {
  const g = e.target.closest("[data-go]");
  if (g) { e.preventDefault(); go(g.dataset.go, g.dataset.sub); return; }
  const m = e.target.closest("[data-mgr]");
  if (m) { openManager(m.dataset.mgr); return; }
  const seg = e.target.closest("[data-seg] .seg-btn");
  if (seg) {
    const name = seg.closest("[data-seg]").dataset.seg;
    onSegment(name, seg.dataset.val);
  }
});

function onSegment(name, val) {
  if (name === "comp") state.comp = val;
  else if (name === "pos") { state.scoringPos = val; state.sim = {}; }
  else if (name === "season") state.season = val;
  else {
    state.sub[name] = val;
    history.replaceState(null, "", "#" + name + "/" + val);
  }
  rerender();
}

/* ==========================================================================
   HOME
   ========================================================================== */

function pitchSvg() {
  return `<svg class="hero-pitch" viewBox="0 0 1000 400" preserveAspectRatio="xMidYMid slice" fill="none" stroke="#c6f432" stroke-width="2">
    <rect x="20" y="20" width="960" height="360" rx="4"/><line x1="500" y1="20" x2="500" y2="380"/>
    <circle cx="500" cy="200" r="70"/><circle cx="500" cy="200" r="3" fill="#c6f432"/>
    <rect x="20" y="105" width="130" height="190"/><rect x="20" y="155" width="50" height="90"/>
    <rect x="850" y="105" width="130" height="190"/><rect x="930" y="155" width="50" height="90"/>
    <path d="M150 160a50 50 0 010 80M850 160a50 50 0 000 80"/></svg>`;
}

RENDERERS.home = () => {
  const meta = D.metadata;
  const leader = CS.standings[0];
  const topPf = CS.standings.slice().sort((a, b) => b.pf - a.pf)[0];
  const topEff = CS.standings.slice().sort((a, b) => b.eff - a.eff)[0];
  const hs = CS.weeklyHighScores.slice(-1)[0];
  const ticks = Array.from({ length: TOTAL_GW }, (_, i) => {
    const gw = i + 1;
    const cls = completed.includes(gw) ? "done" : gw === currentGw || gw === liveGw ? "next" : "";
    const tags = [clGws.has(gw) && "Champions League", cupGws.has(gw) && "Lingineni Cup"].filter(Boolean).join(" · ");
    return `<span class="gw-tick ${cls} ${clGws.has(gw) ? "cl" : ""} ${cupGws.has(gw) ? "cup" : ""}" ${tipAttr(`<strong>Gameweek ${gw}</strong>${{ final: "Completed", live: "In progress", scheduled: "Scheduled" }[gwState(gw)]}${tags ? "<br>" + tags : ""}`)}></span>`;
  }).join("");

  const featured = matchesFor(currentGw);
  const featuredState = gwState(currentGw);
  const upcoming = nextGw > currentGw ? matchesFor(nextGw) : [];

  return `
  <div class="hero">
    ${pitchSvg()}
    <div class="hero-content">
      <div>
        <div class="eyebrow">${esc(meta.edition)} · Season ${esc(meta.season.replace("-", "–"))}</div>
        <h1 class="hero-title display" id="t-home">The Gentlemen's <em>Invitational</em></h1>
        <div class="hero-meta">
          <span class="chip accent"><span class="live-dot"></span>Gameweek ${currentGw} ${featuredState === "final" ? "final" : featuredState === "live" ? "live now" : "up next"}</span>
          <span class="chip">${meta.memberCount} managers</span>
          <span class="chip">${money(meta.totalPrizePool)} prize pool</span>
          <span class="chip">Final day ${esc(meta.dates.finalMatchday)}</span>
          <span class="chip bad">🥞 Last place: 24h IHOP</span>
        </div>
      </div>
      <div class="season-progress">
        <div class="sp-top">
          <div class="sp-gw">GW ${currentGw}<small> / ${TOTAL_GW}</small></div>
          <span class="muted" style="font-size:13px">${completed.length} of ${TOTAL_GW} played</span>
        </div>
        <div class="gw-ticks">${ticks}</div>
        <div class="sp-legend">
          <span><i style="background:var(--accent)"></i>Played</span>
          <span><i style="background:var(--surface-3);box-shadow:inset 0 -3px 0 var(--cl)"></i>Champions League week</span>
          <span><i style="background:var(--surface-3);box-shadow:inset 0 3px 0 var(--cup)"></i>Lingineni Cup week</span>
        </div>
      </div>
    </div>
  </div>

  <div class="grid grid-4" style="margin-bottom:16px">
    <div class="card stat-tile"><span class="stat-label">League leader</span><span class="stat-value">${esc(leader.team)}</span><span class="stat-foot">${leader.pts} pts · ${esc(leader.name)}</span></div>
    <div class="card stat-tile"><span class="stat-label">Most points scored</span><span class="stat-value num">${fmtPts(topPf.pf)}</span><span class="stat-foot">${esc(topPf.team)}</span></div>
    <div class="card stat-tile"><span class="stat-label">GW ${hs ? hs.gw : "–"} high score${hs && hs.live ? `<span class="live-dot" title="Live"></span>` : ""}</span><span class="stat-value num">${hs ? fmtPts(hs.score) : "–"}</span><span class="stat-foot">${!hs ? "No results yet" : hs.live ? `${esc(hs.team)} · leading the race for ${esc(hs.prize)}` : `${esc(hs.team)} · won ${esc(hs.prize)}`}</span></div>
    <div class="card stat-tile"><span class="stat-label">Best lineup efficiency</span><span class="stat-value num">${fmt(topEff.eff, 1)}%</span><span class="stat-foot">${esc(topEff.team)}</span></div>
  </div>

  <div class="grid grid-2">
    <div class="card">
      ${cardHead("Table snapshot", `After gameweek ${lastCompleted}`, `<button class="link-btn" data-go="table">Full table ${ICON.arrow}</button>`)}
      ${snapshotTable()}
    </div>
    <div class="stack">
      <div class="card">
        ${cardHead(`Gameweek ${currentGw} ${featuredState === "final" ? "results" : featuredState === "live" ? "· live scores" : "fixtures"}`, featuredState === "live" ? `Final ${fmtDateTime(gwDates[currentGw] && gwDates[currentGw].end)}` : "Includes cup fixtures that week", `<button class="link-btn" data-go="matches">All matches ${ICON.arrow}</button>`)}
        <div style="padding:6px 0">${featured.length ? featured.map(compactResult).join("") : `<div class="empty" style="margin:14px 20px">No fixtures</div>`}</div>
      </div>
      ${upcoming.length ? `<div class="card">
        ${cardHead(`Up next · Gameweek ${nextGw}`, gwState(nextGw) === "live" ? "Already under way" : upcoming.some(m => m.competition !== "league") ? "Includes cup fixtures" : "Premier League")}
        <div style="padding:6px 0">${upcoming.map(compactResult).join("")}</div>
      </div>` : ""}
    </div>
  </div>

  <div class="card" style="margin-top:16px">
    ${cardHead("Weekly high scores", "$10 to the top scorer every gameweek")}
    ${dataTable("hs", CS.weeklyHighScores.slice().reverse(), [
      { key: "gw", label: "GW", cls: "l strong", render: r => `GW ${r.gw}` },
      { key: "team", label: "Club", cls: "l", render: r => clubCell(r.manager, r.team, { size: "sm" }) },
      { key: "score", label: "Score", cls: "strong", render: r => fmtPts(r.score) },
      { key: "prize", label: "Prize", sortable: false, render: r => r.live ? `<span class="chip accent"><span class="live-dot"></span>Leading</span>` : `<span class="chip accent">${esc(r.prize)}</span>` },
    ])}
  </div>`;
};

function snapshotTable() {
  const rows = CS.standings.length > 7 ? [...CS.standings.slice(0, 6), null, CS.standings[CS.standings.length - 1]] : CS.standings;
  return `<div class="table-wrap"><table class="data"><thead><tr><th class="c">#</th><th class="l">Club</th><th>P</th><th class="hide-sm">+/-</th><th>Pts</th><th class="hide-sm l">Form</th></tr></thead><tbody>
    ${rows.map(s => s ? `<tr class="${zoneClass(s.rank)}"><td class="pos">${s.rank}</td><td class="l club-cell">${clubCell(s.name, s.team, { size: "sm" })}</td><td>${s.p}</td><td class="hide-sm">${esc(s.diff)}</td><td class="strong">${s.pts}</td><td class="hide-sm l">${formPills(s.form)}</td></tr>`
      : `<tr><td colspan="6" class="c dim" style="padding:4px">⋯</td></tr>`).join("")}
  </tbody></table></div>${zoneLegend()}`;
}

function compactResult(m) {
  const played = hasScore(m), final = isFinal(m);
  const hw = final && m.homeScore > m.awayScore, aw = final && m.awayScore > m.homeScore;
  const c = compMeta(m.competition);
  return `<div class="compact-match" ${matchAttr(m)} style="display:grid;grid-template-columns:1fr auto 1fr;gap:10px;align-items:center;padding:8px 20px">
    <div style="display:flex;justify-content:flex-end;align-items:center;gap:8px;min-width:0;text-align:right">
      <span style="min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:${hw ? 700 : 500};color:${final && !hw ? "var(--text-2)" : "var(--text)"}">${esc(m.homeTeam)}</span>${crest(m.home, "sm")}
    </div>
    <div style="text-align:center;min-width:92px">
      ${played ? `<span class="display num" style="font-size:20px">${fmtPts(m.homeScore)} – ${fmtPts(m.awayScore)}</span>` : `<span class="vs-chip">VS</span>`}
      ${m.status === "Live" ? `<div style="font-size:11px;font-weight:700;margin-top:2px">${LIVE_LABEL}</div>` : ""}
      ${c.cls ? `<div class="chip ${c.cls}" style="padding:1px 7px;font-size:10.5px;margin-top:3px">${esc(c.label)}</div>` : ""}
    </div>
    <div style="display:flex;align-items:center;gap:8px;min-width:0">
      ${crest(m.away, "sm")}<span style="min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:${aw ? 700 : 500};color:${final && !aw ? "var(--text-2)" : "var(--text)"}">${esc(m.awayTeam)}</span>
    </div>
  </div>`;
}

function zoneClass(rank) {
  if (rank <= 5) return "zone-cl";
  if (rank === CS.standings.length) return "zone-ihop";
  return "";
}
function zoneLegend() {
  return `<div class="table-legend"><span><i style="background:var(--cl)"></i>Champions League places (1st–5th)</span><span><i style="background:var(--bad)"></i>IHOP penalty (last)</span></div>`;
}

/* ==========================================================================
   TABLE
   ========================================================================== */

RENDERERS.table = () => {
  const view = state.sub.table || "official";
  const views = [
    { id: "official", label: "Official" },
    { id: "optimal", label: "Optimal lineups" },
    { id: "median", label: "vs Median" },
    { id: "efficiency", label: "Efficiency" },
  ];
  const subs = {
    official: "Head-to-head results: 3 points for a win, 1 for a draw.",
    optimal: "Where each club would sit if every manager had started their best possible XI each week.",
    median: "Each week, every club also plays the league median. Shows who's been lucky with the schedule.",
    efficiency: "Points actually scored as a share of the best possible lineup from the same squad.",
  };
  return `
    ${pageHead("table", `After gameweek ${lastCompleted}`, "League Table", subs[view])}
    ${liveGw && view === "official" ? `<p class="dim" style="margin:-10px 0 16px;font-size:13px">${LIVE_LABEL.replace("Live", `Points for and against include live gameweek ${liveGw} scores.`)} Points and W-D-L update when it ends ${esc(fmtDateTime(gwDates[liveGw] && gwDates[liveGw].end))}.</p>` : ""}
    <div class="toolbar">${segmented("table", views, view)}</div>
    <div class="card">${tableViews[view]()}</div>`;
};

const tableViews = {
  official: () => dataTable("official", CS.standings, [
    { key: "rank", label: "#", cls: "pos", title: "Position" },
    { key: "team", label: "Club", cls: "l club-cell", render: r => clubCell(r.name, r.team) },
    { key: "p", label: "P", title: "Played" },
    { key: "w", label: "W", title: "Won", cls: "hide-sm" },
    { key: "d", label: "D", title: "Drawn", cls: "hide-sm" },
    { key: "l", label: "L", title: "Lost", cls: "hide-sm" },
    { key: "pf", label: "PF", title: "Points for", cls: "hide-sm", render: r => fmtPts(r.pf) },
    { key: "pa", label: "PA", title: "Points against", cls: "hide-sm", render: r => fmtPts(r.pa) },
    { key: "diffNum", label: "+/-", title: "Points difference", cls: "hide-sm", render: r => esc(r.diff) },
    { key: "pts", label: "Pts", title: "League points", cls: "strong" },
    { key: "form", label: "Form", cls: "l hide-sm", sortable: false, render: r => formPills(r.form) },
  ], { rowClass: r => zoneClass(r.rank) }) + zoneLegend(),

  optimal: () => dataTable("optimal", CS.optimalStandings, [
    { key: "rank", label: "#", cls: "pos", title: "Optimal position" },
    { key: "team", label: "Club", cls: "l club-cell", render: r => clubCell(r.name, r.team) },
    { key: "record", label: "W-D-L", title: "Record with optimal lineups", sortVal: r => r.pts },
    { key: "pts", label: "Pts", cls: "strong" },
    { key: "optPf", label: "Opt PF", title: "Points scored with optimal lineups", render: r => fmtPts(r.optPf) },
    { key: "actualPf", label: "Actual PF", cls: "hide-sm", render: r => fmtPts(r.actualPf) },
    { key: "benchPoints", label: "Left on bench", render: r => fmtPts(r.benchPoints) },
    { key: "actualRank", label: "Actual #", cls: "hide-sm" },
    { key: "rankShift", label: "Shift", title: "Places gained with optimal lineups", render: r => delta(r.rankShift, r.rankShiftStr) },
  ]),

  median: () => dataTable("median", CS.medianStandings, [
    { key: "rank", label: "#", cls: "pos" },
    { key: "team", label: "Club", cls: "l club-cell", render: r => clubCell(r.name, r.team) },
    { key: "record", label: "Median W-D-L", sortVal: r => r.pts },
    { key: "pts", label: "Pts", cls: "strong" },
    { key: "actualRecord", label: "Actual W-D-L", cls: "hide-sm", sortVal: r => r.actualPts },
    { key: "actualPts", label: "Actual pts", cls: "hide-sm" },
    { key: "luckDiff", label: "Luck", title: "Actual points minus median-schedule points", render: r => delta(r.luckDiff, (r.luckDiff > 0 ? "+" : "") + r.luckDiff) },
    { key: "luckStatus", label: "Verdict", cls: "l hide-sm", render: r => `<span class="chip ${r.luckDiff > 0 ? "accent" : r.luckDiff < 0 ? "bad" : ""}">${esc(r.luckStatus)}</span>` },
  ]),

  efficiency: () => {
    const rows = CS.standings.slice().sort((a, b) => b.eff - a.eff);
    const avg = rows.reduce((s, r) => s + r.eff, 0) / rows.length;
    return `
      ${cardHead("Lineup efficiency", `League average ${fmt(avg, 1)}% · Scale 0–100%`)}
      <div class="bar-list">${rows.map(r => `
        <div class="bar-row" ${tipAttr(`<strong>${esc(r.team)}</strong>Scored ${fmtPts(r.pf)} of a possible ${fmtPts(r.maxPf)}<br>${fmtPts(r.benchPts)} pts left on the bench`)}>
          ${clubCell(r.name, r.team, { size: "sm" })}
          <div class="bar-track"><div class="bar-fill" style="width:${Math.max(0, Math.min(100, r.eff))}%"></div></div>
          <span class="bar-val">${fmt(r.eff, 1)}%</span>
        </div>`).join("")}
      </div>`;
  },
};

/* ==========================================================================
   MATCHES
   ========================================================================== */

RENDERERS.matches = () => {
  const gw = state.gw;
  const all = matchesFor(gw);
  const list = state.comp === "all" ? all : all.filter(m => m.competition === state.comp);
  const groups = {};
  list.forEach(m => (groups[m.competition] = groups[m.competition] || []).push(m));
  const order = ["league", "champions_league", "lingineni_cup"];

  const chips = Array.from({ length: TOTAL_GW }, (_, i) => {
    const g = i + 1;
    return `<button class="gw-chip ${completed.includes(g) ? "done" : ""}" data-gw="${g}" aria-selected="${g === gw}" aria-label="Gameweek ${g}">
      <small>GW</small><b>${g}</b><span class="dots">${completed.includes(g) ? '<i class="d-done"></i>' : ""}${clGws.has(g) ? '<i class="d-cl"></i>' : ""}${cupGws.has(g) ? '<i class="d-cup"></i>' : ""}</span></button>`;
  }).join("");

  return `
    ${pageHead("matches", { final: "Final scores", live: "Live scores", scheduled: "Fixtures" }[gwState(gw)], `Gameweek ${gw}`, gwDates[gw] && gwDates[gw].lastKickoff ? `${fmtDate(gwDates[gw].start)} – last kickoff ${fmtDateTime(gwDates[gw].lastKickoff)}` : "")}
    <div class="gw-strip-wrap">
      <button class="icon-btn" data-gw-step="-1" aria-label="Previous gameweek" ${gw <= 1 ? "disabled" : ""}>${ICON.left}</button>
      <div class="gw-strip" id="gw-strip">${chips}</div>
      <button class="icon-btn" data-gw-step="1" aria-label="Next gameweek" ${gw >= TOTAL_GW ? "disabled" : ""}>${ICON.right}</button>
    </div>
    <div class="toolbar">
      ${segmented("comp", [
        { id: "all", label: "All competitions" },
        { id: "league", label: "Premier League" },
        { id: "champions_league", label: "Champions League" },
        { id: "lingineni_cup", label: "Lingineni Cup" },
      ], state.comp)}
      <span class="dim" style="font-size:13px"><span style="color:var(--accent-text)">●</span> played &nbsp; <span style="color:var(--cl)">●</span> CL &nbsp; <span style="color:var(--cup)">●</span> Cup</span>
    </div>
    <div class="match-groups">
      ${list.length ? order.filter(k => groups[k]).map(k => `
        <div><h3 class="match-group-title">${esc(compMeta(k).label)}${groups[k][0].tournamentStage ? " · " + esc(groups[k][0].tournamentStage) : ""}</h3>
        <div class="match-grid">${groups[k].map(matchCard).join("")}</div></div>`).join("")
        : `<div class="empty">No ${state.comp === "all" ? "" : esc(compMeta(state.comp).label) + " "}matches in gameweek ${gw}.</div>`}
    </div>

    <div class="card" style="margin-top:28px">
      ${cardHead("Head-to-head this season", "Row club's record against column club, all competitions. Hover a cell for details.")}
      ${h2hMatrix()}
    </div>`;
};

afterRender.matches = el => {
  const strip = $("#gw-strip", el);
  const active = $(".gw-chip[aria-selected='true']", el);
  if (strip && active) {
    strip.style.scrollBehavior = "auto";
    strip.scrollLeft = active.offsetLeft - strip.offsetLeft - strip.clientWidth / 2 + active.offsetWidth / 2;
    strip.style.scrollBehavior = "";
  }
};

document.addEventListener("click", e => {
  const chip = e.target.closest("[data-gw]");
  const step = e.target.closest("[data-gw-step]");
  if (!chip && !step) return;
  state.gw = chip ? +chip.dataset.gw : Math.min(TOTAL_GW, Math.max(1, state.gw + +step.dataset.gwStep));
  rerender();
});

function matchCard(m) {
  const played = hasScore(m), final = isFinal(m);
  const c = compMeta(m.competition);
  const h = +m.homeScore, a = +m.awayScore;
  const side = (name, team, score, res) => `
    <div class="match-side ${res}">${clubCell(name, team, { link: false })}<span class="score num">${played ? fmtPts(score) : "–"}</span></div>`;
  const hRes = final ? (h > a ? "win" : h < a ? "lose" : "") : "";
  const aRes = final ? (a > h ? "win" : a < h ? "lose" : "") : "";
  const total = h + a || 1;
  return `<div class="card match ${c.cls}" ${matchAttr(m)}>
    <div class="match-top"><span>${esc(m.tournamentStage || c.label)}</span><span class="${final ? "status-final" : ""}">${final ? "Full time" : played ? LIVE_LABEL : "Scheduled"}</span></div>
    ${side(m.home, m.homeTeam, h, hRes)}
    ${side(m.away, m.awayTeam, a, aRes)}
    ${played ? `<div class="share-bar ${a > h ? "swap" : ""}" ${tipAttr(`Score share: ${fmt(h / total * 100)}% – ${fmt(a / total * 100)}%`)}><i style="flex:${h || 0.0001}"></i><i style="flex:${a || 0.0001}"></i></div>` : ""}
    <div class="match-hint">${played ? "Lineups & player points" : "Lineups"} →</div>
  </div>`;
}

function h2hRecords() {
  const rec = {};
  Object.entries(CS.gameweekMatchups).forEach(([gw, ms]) => ms.forEach(m => {
    if (!isFinal(m)) return;
    const hm = findManager(m.home), am = findManager(m.away);
    if (!hm || !am) return;
    const add = (x, y, r, gwN, sx, sy) => {
      const k = x + "|" + y;
      const o = rec[k] || (rec[k] = { w: 0, d: 0, l: 0, games: [] });
      o[r]++; o.games.push({ gw: gwN, s: sx, o: sy });
    };
    const hr = m.homeScore > m.awayScore ? "w" : m.homeScore < m.awayScore ? "l" : "d";
    const ar = hr === "w" ? "l" : hr === "l" ? "w" : "d";
    add(hm.id, am.id, hr, +gw, m.homeScore, m.awayScore);
    add(am.id, hm.id, ar, +gw, m.awayScore, m.homeScore);
  }));
  return rec;
}

function h2hMatrix() {
  const rec = h2hRecords();
  const mgrs = CS.standings.map(s => managerById[s.managerId]).filter(Boolean);
  const head = `<tr><th></th>${mgrs.map(m => `<th title="${esc(m.teamName)}">${esc(m.shortName)}</th>`).join("")}</tr>`;
  const rows = mgrs.map(r => `<tr><th class="row-h">${esc(r.teamName)}</th>${mgrs.map(c => {
    if (r.id === c.id) return `<td class="self"></td>`;
    const o = rec[r.id + "|" + c.id];
    if (!o) return `<td ${tipAttr(`<strong>${esc(r.teamName)} vs ${esc(c.teamName)}</strong>Not played yet`)}>·</td>`;
    const diff = o.w - o.l;
    const cls = diff >= 2 ? "pos2" : diff === 1 ? "pos1" : diff === 0 ? "mid" : diff === -1 ? "neg1" : "neg2";
    const games = o.games.map(g => `GW ${g.gw}: ${fmtPts(g.s)} – ${fmtPts(g.o)}`).join("<br>");
    return `<td class="${cls}" ${tipAttr(`<strong>${esc(r.teamName)} vs ${esc(c.teamName)}</strong>${o.w}W ${o.d}D ${o.l}L<br>${games}`)}>${o.w}-${o.l}${o.d ? "-" + o.d : ""}</td>`;
  }).join("")}</tr>`).join("");
  return `<div class="h2h-wrap"><table class="h2h"><thead>${head}</thead><tbody>${rows}</tbody></table></div>
    <div class="h2h-legend"><span>Losing record</span><i style="background:var(--div-neg-2)"></i><i style="background:var(--div-neg-1)"></i><i style="background:var(--div-mid)"></i><i style="background:var(--div-pos-1)"></i><i style="background:var(--div-pos-2)"></i><span>Winning record</span><span class="dim" style="margin-left:10px">· not played</span></div>`;
}

/* ==========================================================================
   CUPS
   ========================================================================== */

RENDERERS.cups = () => {
  const view = state.sub.cups || "cl";
  return `
    ${pageHead("cups", "Knockout silverware", view === "cl" ? "Champions League" : "Lingineni Cup",
      view === "cl" ? "Six-club group stage, then two-legged semi-finals and a one-off final." : D.lingineniCup.format)}
    <div class="toolbar">${segmented("cups", [{ id: "cl", label: "⭐ Champions League" }, { id: "cup", label: "🏆 Lingineni Cup" }], view)}</div>
    ${view === "cl" ? championsLeague() : lingineniCup()}`;
};

function clStages() {
  const cl = D.championsLeague;
  const stages = (cl.groupSchedule || []).map((g, i) => ({ gw: +g.gw, label: `Matchday ${i + 1}`, short: `MD${i + 1}`, group: true }));
  const ko = new Map();
  Object.entries(CS.gameweekMatchups).forEach(([gw, ms]) => ms.forEach(m => {
    if (m.competition === "champions_league" && !/^Group Stage/.test(m.tournamentStage || "") && !ko.has(+gw)) ko.set(+gw, m.tournamentStage);
  }));
  [...ko.entries()].sort((a, b) => a[0] - b[0]).forEach(([gw, stage]) => {
    const short = /Final/.test(stage) && !/Semi/.test(stage) ? "Final" : /Leg 1/.test(stage) ? "SF L1" : /Leg 2/.test(stage) ? "SF L2" : stage;
    stages.push({ gw, label: stage.replace(" 🏆", ""), short, group: false });
  });
  stages.forEach(s => {
    const ms = matchesFor(s.gw).filter(m => m.competition === "champions_league");
    s.matches = ms;
    s.done = ms.length > 0 && ms.every(isFinal);
  });
  const next = stages.find(s => !s.done);
  if (next) next.next = true;
  return stages;
}

function clMatchLine(m) {
  const played = hasScore(m), final = isFinal(m);
  const h = +m.homeScore, a = +m.awayScore;
  const side = (team, won) => `<b style="${final && !won ? "font-weight:500;color:var(--text-2)" : ""}">${esc(team)}</b>`;
  const score = played
    ? `<span class="num" style="font-weight:800;padding:2px 8px;border-radius:6px;background:var(--surface-2);font-size:13px">${fmtPts(h)} – ${fmtPts(a)}</span>`
    : `<span class="vs">vs</span>`;
  return `<div ${matchAttr(m)}>${crest(m.home, "sm")}${side(m.homeTeam, h > a)}${score}${side(m.awayTeam, a > h)}${crest(m.away, "sm")}</div>`;
}

function championsLeague() {
  const cl = D.championsLeague;
  const stages = clStages();
  const groupStages = stages.filter(s => s.group);
  const doneGroup = groupStages.filter(s => s.done).length;
  const latest = stages.filter(s => s.done).slice(-1)[0];
  const next = stages.find(s => s.next);

  // Form per club from completed group fixtures, in gameweek order
  const form = {};
  groupStages.filter(s => s.done).forEach(s => s.matches.forEach(m => {
    const h = +m.homeScore, a = +m.awayScore;
    (form[m.homeTeam] = form[m.homeTeam] || []).push(h > a ? "W" : h < a ? "L" : "D");
    (form[m.awayTeam] = form[m.awayTeam] || []).push(a > h ? "W" : a < h ? "L" : "D");
  }));

  const tracker = `<div class="card card-pad" style="margin-bottom:16px">
    <div style="display:flex;justify-content:space-between;align-items:baseline;gap:12px;flex-wrap:wrap;margin-bottom:14px">
      <div><div class="stat-label">Group stage</div><div class="display" style="font-size:28px;margin-top:4px">Matchday ${doneGroup} of ${groupStages.length} complete</div></div>
      ${next ? `<span class="chip cl"><span class="live-dot" style="background:var(--cl)"></span>Next: ${esc(next.label)} · GW ${next.gw}</span>` : `<span class="chip cup">Tournament complete</span>`}
    </div>
    <div style="display:grid;grid-template-columns:repeat(${stages.length},minmax(0,1fr));gap:4px">
      ${stages.map(s => `<div ${tipAttr(`<strong>${esc(s.label)}</strong>GW ${s.gw} · ${s.done ? "Completed" : s.next ? "Up next" : "Scheduled"}`)}>
        <div style="height:6px;border-radius:3px;background:${s.done ? "var(--cl)" : s.next ? "color-mix(in srgb, var(--cl) 35%, transparent)" : "var(--surface-3)"}"></div>
        <div style="font-size:11px;font-weight:700;letter-spacing:.06em;margin-top:6px;color:${s.done || s.next ? "var(--text)" : "var(--text-3)"};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(s.short)}</div>
        <div class="dim" style="font-size:11px">GW ${s.gw}</div></div>`).join("")}
    </div>
  </div>`;

  const latestCard = latest ? `<div style="margin-bottom:16px">
      <h3 class="match-group-title">Latest results · ${esc(latest.label)} · GW ${latest.gw}</h3>
      <div class="match-grid">${latest.matches.map(matchCard).join("")}</div>
    </div>` : "";

  const schedule = groupStages.map((s, i) => {
    const g = cl.groupSchedule[i];
    const lines = s.matches.length ? s.matches.map(clMatchLine).join("") : [g.m1, g.m2, g.m3].filter(Boolean).map(x => `<div>${esc(x)}</div>`).join("");
    const badge = s.done ? `<span class="chip" style="padding:2px 8px;font-size:11px;margin-top:8px;font-family:var(--font-body)">FT</span>` : s.next ? `<span class="chip cl" style="padding:2px 8px;font-size:11px;margin-top:8px;font-family:var(--font-body)">Next</span>` : "";
    return `<li><div class="tl-gw">GW ${s.gw}<small>MATCHDAY ${i + 1}</small>${badge}</div><div class="tl-matches">${lines}</div></li>`;
  }).join("");

  return `
    ${tracker}
    ${latestCard}
    <div style="margin-bottom:16px">
      <div class="card">
          ${cardHead("Group table", `After matchday ${doneGroup} · Top 4 advance to the semi-finals`)}
          ${dataTable("clgroup", cl.currentGroupTable, [
            { key: "pos", label: "#", cls: "pos" },
            { key: "team", label: "Club", cls: "l club-cell", render: r => clubCell(r.name, r.team) },
            { key: "p", label: "P", title: "Played", sortVal: r => r.w + r.d + r.l, render: r => r.w + r.d + r.l },
            { key: "w", label: "W" }, { key: "d", label: "D", cls: "hide-sm" }, { key: "l", label: "L" },
            { key: "pf", label: "PF", cls: "hide-sm", render: r => fmtPts(r.pf) },
            { key: "pa", label: "PA", cls: "hide-sm", render: r => fmtPts(r.pa) },
            { key: "gd", label: "+/-", title: "Points difference", cls: "hide-sm", sortVal: r => r.pf - r.pa, render: r => { const d = r.pf - r.pa; return (d > 0 ? "+" : "") + fmt(d, 2); } },
            { key: "pts", label: "Pts", cls: "strong" },
            { key: "form", label: "Form", cls: "l hide-sm", sortable: false, render: r => formPills(form[r.team] || [], groupStages.length) },
          ], { rowClass: r => (r.pos <= 4 ? "zone-cl" : "") })}
          <div class="table-legend"><span><i style="background:var(--cl)"></i>Semi-final places</span></div>
        </div>
    </div>
    <div class="grid grid-2">
      <div class="card">
        ${cardHead("Group stage schedule", "Played alongside the league fixture that week")}
        <ol class="timeline">${schedule}</ol>
      </div>
      <div>
        <div class="card">
          ${cardHead("Knockout stage")}
          ${cl.knockoutSchedule.map(k => `<div class="ko-card"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><h4>${esc(k.round)}</h4><span class="chip cl">${esc(k.gws)}</span></div>
            <p class="card-sub" style="margin-bottom:8px">${esc(k.format)}</p>
            ${[k.m1, k.m2].filter(Boolean).map(s => `<div style="font-size:14px;padding:3px 0">${esc(s)}</div>`).join("")}</div>`).join("")}
        </div>
      </div>
    </div>
    <div class="card" style="margin-top:16px">
      ${cardHead("Qualified clubs", "Last season's top finishers plus the reigning champion")}
      <div class="qual-grid">${cl.qualifiers.map(q => `
        <div class="qual"><span class="seed">SEED ${esc(q.code)}</span>${clubCell(q.name, q.team)}<div class="reason">${esc(q.reason)}</div></div>`).join("")}
      </div>
    </div>`;
}

function parseEntrant(s) {
  const m = String(s).match(/^(.*?)\s*\((.*)\)$/);
  const name = m ? m[1] : s;
  const mgr = managerByName[name] || null;
  if (!mgr) return { tbd: true, label: s };
  return { mgr, team: m && m[2] !== "Bye" ? m[2] : mgr.teamName, bye: m && m[2] === "Bye" };
}

function lingineniCup() {
  const rounds = D.lingineniCup.rounds;
  const tieSide = (s, winner) => {
    const e = parseEntrant(s);
    if (e.tbd) return `<div class="tie-side tbd"><span class="crest sm tbd" aria-hidden="true">?</span><span class="t-name">${esc(e.label)}</span></div>`;
    const won = winner && winner !== "TBD" && String(winner).includes(e.mgr.name);
    return `<div class="tie-side ${won ? "won" : ""}">${crest(e.mgr, "sm")}<button class="club-btn t-name" data-mgr="${e.mgr.id}"><span class="club-name">${esc(e.mgr.name)}</span><span class="t-team">${esc(e.team)}${e.bye ? " · Bye" : ""}</span></button></div>`;
  };
  return `
    <div class="card">
      ${cardHead("Bracket", "Scroll sideways on smaller screens")}
      <div class="bracket">${rounds.map((r, i) => `
        <div class="round ${i === rounds.length - 1 ? "final" : ""}">
          <div class="round-head"><b>${esc(r.name)}</b><span>${esc(r.gw)}</span></div>
          <div class="round-body">${r.matches.map(m => `<div class="tie"><span class="tie-id">${esc(m.id)}</span>${tieSide(m.p1, m.winner)}${tieSide(m.p2, m.winner)}</div>`).join("")}</div>
        </div>`).join("")}
      </div>
    </div>`;
}

/* ==========================================================================
   MANAGERS
   ========================================================================== */

RENDERERS.managers = () => {
  const list = CS.standings.map(s => managerById[s.managerId]).filter(Boolean);
  Object.values(managerById).forEach(m => { if (!list.includes(m)) list.push(m); });
  return `
    ${pageHead("managers", `${list.length} clubs · ${D.metadata.cities.length} cities`, "Managers", "Tap a club to open the full dossier.")}
    <div class="mgr-grid">${list.map(m => {
      const s = standingById[m.id];
      const c = m.careerRecord || {};
      return `<button class="card mgr-card" data-mgr="${m.id}" style="--c:${m.color}">
        <span class="mgr-band"></span>
        <span class="mgr-body">
          <span class="mgr-top">${crest(m)}<span style="min-width:0"><span class="mgr-team" style="display:block">${esc(m.teamName)}</span><span class="mgr-name" style="display:block">${esc(m.name)} · ${esc(m.city)}</span></span>
            ${s ? `<span class="mgr-rank"><b>${ordinal(s.rank)}</b><small>${s.pts} PTS</small></span>` : ""}</span>
          <span style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap">
            <span class="chip ${/Commissioner/.test(m.role) ? "accent" : ""}">${esc(m.role)}</span>
            ${s ? formPills(s.form) : ""}
          </span>
          ${m.accolades && m.accolades.length ? `<span class="trophies">${m.accolades.map(a => `<span class="chip cup">🏆 ${esc(a)}</span>`).join("")}</span>` : ""}
          <span class="mgr-stats">
            <span><small>Career</small><b class="num">${c.w ?? 0}-${c.d ?? 0}-${c.l ?? 0}</b></span>
            <span><small>Pts / wk</small><b class="num">${c.ppg != null ? fmt(c.ppg, 2) : "–"}</b></span>
            <span><small>Winnings</small><b class="num">${money(m.careerMoney || 0)}</b></span>
          </span>
        </span>
      </button>`;
    }).join("")}</div>`;
};

function openManager(id) {
  const m = managerById[id];
  if (!m) return;
  const s = standingById[id];
  const c = m.careerRecord || {};
  const fixtures = [];
  for (let gw = 1; gw <= TOTAL_GW; gw++) {
    matchesFor(gw).forEach(x => {
      if (x.home !== m.name && x.away !== m.name) return;
      const home = x.home === m.name;
      fixtures.push({ gw, comp: x.competition, stage: x.tournamentStage, opp: home ? x.away : x.home, oppTeam: home ? x.awayTeam : x.homeTeam, us: home ? x.homeScore : x.awayScore, them: home ? x.awayScore : x.homeScore, played: isFinal(x), live: x.status === "Live", home, match: x });
    });
  }
  const played = fixtures.filter(f => f.played);
  const upcoming = fixtures.filter(f => !f.played).slice(0, 5);
  const fixtureRow = f => {
    const r = f.played ? (f.us > f.them ? "W" : f.us < f.them ? "L" : "D") : "";
    const cm = compMeta(f.comp);
    return `<div class="fixture" ${matchAttr(f.match)}><span class="gw">GW ${f.gw}</span>${crest(f.opp, "sm")}<span style="min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${f.home ? "vs" : "@"} <b>${esc(f.oppTeam)}</b>${cm.cls ? ` <span class="chip ${cm.cls}" style="padding:0 7px;font-size:10.5px">${cm.cls === "cl" ? "UCL" : "Cup"}</span>` : ""}</span>
      ${f.played ? `<span style="display:flex;gap:8px;align-items:center"><span class="num">${fmtPts(f.us)} – ${fmtPts(f.them)}</span><span class="f-pill f-${r}">${r}</span></span>`
        : f.live ? `<span style="display:flex;gap:8px;align-items:center;font-size:12.5px"><span class="num">${fmtPts(f.us)} – ${fmtPts(f.them)}</span>${LIVE_LABEL}</span>`
        : `<span class="dim" style="font-size:12.5px">Scheduled</span>`}</div>`;
  };

  $("#mgr-modal").style.setProperty("--c", m.color);
  $("#mgr-modal").innerHTML = `
    <div class="modal-hero">
      ${crest(m, "lg")}
      <div style="min-width:0">
        <div class="eyebrow" style="margin-bottom:2px">${esc(m.role)}</div>
        <h2 class="display" style="margin:0;font-size:36px">${esc(m.teamName)}</h2>
        <div class="muted">${esc(m.name)} · ${esc(m.city)}</div>
      </div>
      <button class="icon-btn modal-close" data-close aria-label="Close">${ICON.close}</button>
    </div>
    <div class="modal-body">
      ${m.bio ? `<p style="margin:0;color:var(--text-2);font-size:15px">${esc(m.bio)}</p>` : ""}
      ${m.accolades && m.accolades.length ? `<div class="trophies">${m.accolades.map(a => `<span class="chip cup">🏆 ${esc(a)}</span>`).join("")}</div>` : ""}
      ${s ? `<div class="modal-section"><h4>This season</h4><div class="kv-grid">
        <div class="kv"><small>Position</small><b>${ordinal(s.rank)}</b></div>
        <div class="kv"><small>Points</small><b>${s.pts}</b></div>
        <div class="kv"><small>Points for</small><b>${fmtPts(s.pf)}</b></div>
        <div class="kv"><small>Efficiency</small><b>${fmt(s.eff, 1)}%</b></div>
      </div></div>` : ""}
      <div class="modal-section"><h4>Career</h4><div class="kv-grid">
        <div class="kv"><small>Record</small><b>${c.w ?? 0}-${c.d ?? 0}-${c.l ?? 0}</b></div>
        <div class="kv"><small>Pts / week</small><b>${c.ppg != null ? fmt(c.ppg, 2) : "–"}</b></div>
        <div class="kv"><small>Weeks</small><b>${c.weeks ?? 0}</b></div>
        <div class="kv"><small>Winnings</small><b>${money(m.careerMoney || 0)}</b></div>
      </div></div>
      ${m.teamId ? `<div class="modal-section"><h4>Current squad</h4><div id="squad-list">${skeletonRows(6)}</div></div>` : ""}
      ${played.length ? `<div class="modal-section"><h4>Results</h4><div class="fixture-list">${played.map(fixtureRow).join("")}</div></div>` : ""}
      ${upcoming.length ? `<div class="modal-section"><h4>Next up</h4><div class="fixture-list">${upcoming.map(fixtureRow).join("")}</div></div>` : ""}
    </div>`;
  openOverlay("#mgr-overlay");
  if (m.teamId) loadSquad(m.teamId);
}

/* ==========================================================================
   LINEUPS (matchup view and current squad, loaded from the hub server on demand)
   ========================================================================== */

const POS_ORDER = ["G", "D", "M", "F"];
const POS_NAMES = { G: "Goalkeeper", D: "Defenders", M: "Midfielders", F: "Forwards" };
const LINEUP_API_HELP = "Lineups come from Fantrax through the hub server, so they only load when the site runs on app.py (locally or on Render).";

function skeletonRows(n) { return Array.from({ length: n }, () => `<div class="skeleton"></div>`).join(""); }

// "COV 1 @TOT 3 F" -> "COV 1–3 TOT"; anything else (e.g. an upcoming kickoff) is shown as Fantrax sends it.
function prettyGame(game) {
  const m = String(game || "").match(/^([A-Z]{2,4}) (\d+) @([A-Z]{2,4}) (\d+)/);
  return m ? `${m[1]} ${m[2]}–${m[4]} ${m[3]}` : String(game || "").replace(/@/g, "@ ");
}

async function fetchJson(url) {
  const res = await fetch(url, { headers: { Accept: "application/json" } });
  const body = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(body.error || `HTTP ${res.status}`);
  return body;
}

function playerRow(p, { bench = false, star = false, showSeason = false } = {}) {
  const pos = p.slot || (p.positions || "").split(",")[0] || "–";
  const meta = showSeason
    ? [p.club, p.positions && p.positions.replace(/,/g, "/"), `${p.games_played} GP`].filter(Boolean).join(" · ")
    : [p.club, p.game && prettyGame(p.game), p.minutes ? `${p.minutes}′` : (p.game ? "DNP" : "")].filter(Boolean).join(" · ");
  return `<div class="lu-row ${bench ? "bench" : ""}">
    <span class="pos-tag" title="${esc(POS_NAMES[pos] || pos)}">${esc(pos)}</span>
    <span style="min-width:0"><span class="nm" style="display:block">${esc(p.name)}${star ? `<span class="star" title="Top scorer in this matchup">★</span>` : ""}</span><span class="meta" style="display:block">${esc(meta)}</span></span>
    <span class="pts ${p.points < 0 ? "neg" : ""}">${fmtPts(p.points)}</span>
  </div>`;
}

function lineupColumn(lu, starId) {
  if (!lu) return `<div class="lu-col"><div class="empty">No lineup returned</div></div>`;
  const benchPts = lu.bench.reduce((t, p) => t + p.points, 0);
  return `<div class="lu-col">
    <div class="lu-section"><span>Starting XI</span><span>Pts</span></div>
    ${lu.starters.map(p => playerRow(p, { star: p.id === starId })).join("")}
    <div class="lu-total"><span>Starters total</span><b class="num">${fmtPts(lu.total)}</b></div>
    <div class="lu-section"><span>Bench</span><span>Pts</span></div>
    ${lu.bench.length ? lu.bench.map(p => playerRow(p, { bench: true })).join("") : `<div class="dim" style="font-size:13px">Empty</div>`}
    <div class="lu-total"><span>Left on the bench</span><b class="num">${fmtPts(benchPts)}</b></div>
    ${lu.injured_reserve.length ? `<div class="lu-section"><span>Injured reserve</span><span></span></div>${lu.injured_reserve.map(p => playerRow(p, { bench: true })).join("")}` : ""}
  </div>`;
}

async function openMatchup(m) {
  closeOverlays();
  const final = isFinal(m), live = m.status === "Live";
  const hId = teamIdByName[m.homeTeam], aId = teamIdByName[m.awayTeam];
  const c = compMeta(m.competition);
  const side = (name, team, cls) => `<div class="side ${cls}">${cls === "away" ? "" : crest(name, "lg")}<div style="min-width:0"><div class="team">${esc(team)}</div><div class="mgr">${esc(name)}</div></div>${cls === "away" ? crest(name, "lg") : ""}</div>`;
  const note = final ? "" : live ? `${LIVE_LABEL.replace("Live", "Live scores. Points can still change until the gameweek officially ends.")}` : "These are the lineups currently set. Managers can change them until each player's match kicks off.";
  $("#match-modal").innerHTML = `
    <div class="lu-head">
      ${side(m.home, m.homeTeam, "home")}
      <div class="lu-score"><b class="num">${hasScore(m) ? `${fmtPts(m.homeScore)} – ${fmtPts(m.awayScore)}` : "vs"}</b><small>GW ${m.gw} · ${esc(m.tournamentStage || c.label)}</small></div>
      ${side(m.away, m.awayTeam, "away")}
      <button class="icon-btn modal-close" data-close aria-label="Close">${ICON.close}</button>
    </div>
    ${note ? `<div class="lu-note">${note}</div>` : ""}
    <div class="lu-grid" id="lu-grid"><div class="lu-col">${skeletonRows(11)}</div><div class="lu-col">${skeletonRows(11)}</div></div>`;
  openOverlay("#match-overlay");

  const grid = $("#lu-grid");
  if (!hId || !aId) { grid.innerHTML = `<div class="lu-col"><div class="empty">No Fantrax team id for this matchup. Re-run the sync.</div></div>`; return; }
  try {
    const data = await fetchJson(`/api/lineups/${m.gw}?teams=${encodeURIComponent(hId)},${encodeURIComponent(aId)}`);
    const hl = data.lineups[hId], al = data.lineups[aId];
    const starters = [...(hl ? hl.starters : []), ...(al ? al.starters : [])];
    const top = starters.length && hasScore(m) ? starters.reduce((b, p) => (p.points > b.points ? p : b)) : null;
    if (grid.isConnected) grid.innerHTML = lineupColumn(hl, top && top.id) + lineupColumn(al, top && top.id);
  } catch (err) {
    if (grid.isConnected) grid.innerHTML = `<div class="lu-col" style="grid-column:1/-1"><div class="empty">Couldn't load lineups (${esc(err.message)}).<br>${esc(LINEUP_API_HELP)}</div></div>`;
  }
}

async function loadSquad(teamId) {
  const box = () => $("#squad-list");
  try {
    const data = await fetchJson(`/api/squad/${encodeURIComponent(teamId)}`);
    const groups = [["starter", "Starting XI"], ["bench", "Bench"], ["injured_reserve", "Injured reserve"]];
    const html = groups.map(([key, label]) => {
      const ps = data.players.filter(p => p.status === key);
      return ps.length ? `<div class="lu-section"><span>${label}</span><span>Season pts</span></div>${ps.map(p => playerRow(p, { bench: key !== "starter", showSeason: true })).join("")}` : "";
    }).join("");
    if (box()) box().innerHTML = html || `<div class="dim">No players returned.</div>`;
  } catch (err) {
    if (box()) box().innerHTML = `<div class="empty">Couldn't load the squad (${esc(err.message)}).<br>${esc(LINEUP_API_HELP)}</div>`;
  }
}

document.addEventListener("click", e => {
  const el = e.target.closest("[data-match]");
  if (!el || e.target.closest("[data-mgr]")) return;
  const m = findMatch(el.dataset.match);
  if (m) openMatchup(m);
});
document.addEventListener("keydown", e => {
  if (e.key !== "Enter" && e.key !== " ") return;
  const el = e.target.closest && e.target.closest("[data-match]");
  if (!el || el !== e.target) return;
  e.preventDefault();
  const m = findMatch(el.dataset.match);
  if (m) openMatchup(m);
});

/* ==========================================================================
   HISTORY
   ========================================================================== */

RENDERERS.history = () => {
  const view = state.sub.history || "alltime";
  const h = D.history;
  const views = [
    { id: "alltime", label: "All-time table" },
    { id: "money", label: "Prize money" },
    { id: "seasons", label: "Past seasons" },
    { id: "shame", label: "Wall of Shame" },
  ];
  let body = "";
  if (view === "alltime") {
    body = `<div class="card">${dataTable("alltime", h.allTimeRankings, [
      { key: "rank", label: "#", cls: "pos" },
      { key: "player", label: "Manager", cls: "l club-cell", render: r => { const m = findManager(r.player); return m ? clubCell(m.name, m.teamName) : `<span class="club">${crest(r.player)}<span class="club-text"><span class="club-name">${esc(r.player)}</span></span></span>`; } },
      { key: "weeks", label: "Weeks", cls: "hide-sm" },
      { key: "w", label: "W" }, { key: "d", label: "D", cls: "hide-sm" }, { key: "l", label: "L" },
      { key: "pts", label: "Pts" },
      { key: "ppw", label: "Pts/wk", cls: "strong", render: r => fmt(r.ppw, 2) },
      { key: "status", label: "Status", cls: "l hide-sm", render: r => r.status ? `<span class="chip ${/Relegated|Banned|Banished/i.test(r.status) ? "bad" : ""}">${esc(r.status)}</span>` : "" },
    ])}</div>`;
  } else if (view === "money") {
    const rows = h.prizeMoneyLeaderboard.slice().sort((a, b) => b.money - a.money);
    const max = Math.max(...rows.map(r => r.money), 1);
    body = `<div class="card">${cardHead("Career winnings", `${money(rows.reduce((s, r) => s + r.money, 0))} paid out across all seasons`)}
      <div class="bar-list">${rows.map(r => `
        <div class="bar-row" ${tipAttr(`<strong>${esc(r.manager)}</strong>Finishes: ${esc(r.finishes)}${r.accolades ? "<br>" + esc(r.accolades) : ""}`)}>
          ${(() => { const m = findManager(r.manager); return m ? clubCell(m.name, m.teamName, { size: "sm" }) : `<span class="club">${crest(r.manager, "sm")}<span class="club-text"><span class="club-name">${esc(r.manager)}</span></span></span>`; })()}
          <div class="bar-track"><div class="bar-fill cup" style="width:${r.money / max * 100}%"></div></div>
          <span class="bar-val">${money(r.money)}</span>
        </div>`).join("")}</div></div>`;
  } else if (view === "seasons") {
    const keys = Object.keys(h.seasons).sort().reverse();
    if (!h.seasons[state.season]) state.season = keys[0];
    const s = h.seasons[state.season];
    const honour = (label, cls, data) => data ? `<div class="honour"><small style="color:var(--${cls})">${label}</small><div class="who">${esc(data.winner)}</div><div class="detail">Runner-up: ${esc(data.runnerUp || "–")}${data.finalMatch ? "<br>" + esc(data.finalMatch) : ""}${data.knockout && data.knockout.final ? "<br>" + esc(data.knockout.final) : ""}</div></div>` : "";
    body = `
      <div class="toolbar">${segmented("season", keys.map(k => ({ id: k, label: k.replace(/^20(\d\d)-20(\d\d)$/, "20$1–$2") })), state.season)}</div>
      <div class="grid grid-2">
        <div class="card">
          ${cardHead(`${state.season.replace("-", "–")} season`)}
          <div class="season-summary">${esc(s.summary)}</div>
          ${(s.championsLeague || s.lingineniCup) ? `<div class="honours">${honour("⭐ Champions League", "cl", s.championsLeague)}${honour("🏆 Lingineni Cup", "cup", s.lingineniCup)}</div>` : ""}
        </div>
        <div class="card">
          ${cardHead("Final standings")}
          ${dataTable("season-" + state.season, s.standings, [
            { key: "rank", label: "#", cls: "pos" },
            { key: "player", label: "Manager", cls: "l", render: r => `<span class="club">${crest(r.player, "sm")}<span class="club-text"><span class="club-name">${esc(r.player)}</span>${r.note ? `<span class="club-mgr">${esc(r.note)}</span>` : ""}</span></span>` },
            { key: "w", label: "W" }, { key: "l", label: "L" },
            { key: "pts", label: "Pts", cls: "strong" },
          ], { rowClass: r => (r.rank === 1 ? "zone-champ" : r.rank === s.standings.length ? "zone-ihop" : "") })}
        </div>
      </div>`;
  } else {
    body = `<div class="grid grid-2">${h.wallOfShame.map(w => `
      <div class="card shame-card"><div class="eyebrow" style="color:var(--bad-text)">${esc(w.season)}</div><h4>${esc(w.name)}</h4>
        <span class="label">The crime</span><p>${esc(w.crime)}</p>
        <span class="label">The sentence</span><p>${esc(w.fate)}</p></div>`).join("")}</div>`;
  }
  return `${pageHead("history", "Since 2023", "League History", "Every season, every dollar, every disgrace.")}
    <div class="toolbar">${segmented("history", views, view)}</div>${body}`;
};

/* ==========================================================================
   RULES
   ========================================================================== */

RENDERERS.rules = () => {
  const view = state.sub.rules || "prizes";
  const views = [
    { id: "prizes", label: "Prize pool" },
    { id: "scoring", label: "Scoring" },
    { id: "ihop", label: "🥞 IHOP Challenge" },
    { id: "bylaws", label: "Constitution" },
  ];
  const bodies = { prizes: rulesPrizes, scoring: rulesScoring, ihop: rulesIhop, bylaws: rulesBylaws };
  return `${pageHead("rules", `${money(D.metadata.buyIn)} buy-in · ${D.metadata.memberCount} managers`, "Rules & Prizes", "")}
    <div class="toolbar">${segmented("rules", views, view)}</div>${bodies[view]()}`;
};

function rulesPrizes() {
  const total = D.prizes.reduce((s, p) => s + p.amount, 0);
  return `
    <div class="grid grid-3">${D.prizes.map(p => `
      <div class="card prize-card">
        <span class="prize-icon" aria-hidden="true">${p.icon}</span>
        <div style="min-width:0;flex:1">
          <div class="prize-amt num">${money(p.amount)}</div>
          <div class="prize-name">${esc(p.rank)}</div>
          <div class="prize-desc">${esc(p.desc)}</div>
          <div class="bar-track" style="margin-top:12px" ${tipAttr(`${fmt(p.amount / total * 100, 1)}% of the ${money(total)} pool`)}><div class="bar-fill" style="width:${p.amount / total * 100}%"></div></div>
          <div class="dim" style="font-size:12px;margin-top:4px">${fmt(p.amount / total * 100, 1)}% of pool</div>
        </div>
      </div>`).join("")}
    </div>
    <div class="card card-pad" style="margin-top:16px;display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap">
      <div><div class="stat-label">Total prize pool</div><div class="stat-value">${money(total)}</div></div>
      <div class="muted" style="max-width:52ch">${D.metadata.memberCount} managers × ${money(D.metadata.buyIn)}. The weekly prize pays ${money(10)} to the top scorer in each of the ${TOTAL_GW} gameweeks.</div>
    </div>`;
}

function statAbbr(stat) {
  const m = stat.match(/\(([^)]+)\)/);
  return m ? m[1] : stat;
}

function rulesScoring() {
  const pos = state.scoringPos;
  const rules = D.scoringMatrix[pos] || [];
  const posNames = { G: "Goalkeeper", D: "Defender", M: "Midfielder", F: "Forward" };
  const groups = [
    { id: "attacking", label: "Attacking" },
    { id: "defensive", label: "Defensive" },
    { id: "negative", label: "Penalties" },
  ];
  const total = rules.reduce((s, r) => s + (state.sim[r.stat] || 0) * r.pts, 0);
  return `
    <div class="toolbar">${segmented("pos", Object.entries(posNames).map(([id, label]) => ({ id, label })), pos)}</div>
    <div class="scoring-layout">
      <div class="card">
        ${cardHead(`${posNames[pos]} scoring`, `${rules.length} scoring categories`)}
        ${groups.map(g => {
          const rs = rules.filter(r => r.type === g.id);
          if (!rs.length) return "";
          return `<div class="rule-group"><h5>${g.label}</h5>${rs.map(r => `<div class="rule-row"><span>${esc(r.stat)}</span><span class="pts-badge ${r.pts < 0 ? "pts-neg" : "pts-pos"}">${r.pts > 0 ? "+" : ""}${r.pts}</span></div>`).join("")}</div>`;
        }).join("")}
      </div>
      <div class="card sim">
        ${cardHead("Points simulator", "Enter a stat line to see what it scores", `<button class="link-btn" data-sim-reset>Reset</button>`)}
        <div class="sim-grid">${rules.map(r => `
          <div class="stepper"><label for="sim-${statAbbr(r.stat)}" title="${esc(r.stat)}">${esc(r.stat.replace(/\s*\([^)]*\)/, ""))}</label>
            <span class="stepper-ctl"><button data-sim-step="-1" data-stat="${esc(r.stat)}" aria-label="Decrease">−</button><input id="sim-${statAbbr(r.stat)}" type="number" min="0" inputmode="numeric" data-sim-input="${esc(r.stat)}" value="${state.sim[r.stat] || 0}"><button data-sim-step="1" data-stat="${esc(r.stat)}" aria-label="Increase">+</button></span>
          </div>`).join("")}</div>
        <div class="sim-total"><div><div class="stat-label">Fantasy points</div><div class="dim" style="font-size:12.5px">${posNames[pos]} · single match</div></div><span class="big num" id="sim-total">${fmtPts(total)}</span></div>
      </div>
    </div>`;
}

function updateSimTotal() {
  const rules = D.scoringMatrix[state.scoringPos] || [];
  const total = rules.reduce((s, r) => s + (state.sim[r.stat] || 0) * r.pts, 0);
  const el = $("#sim-total");
  if (el) el.textContent = fmtPts(total);
}

document.addEventListener("click", e => {
  const b = e.target.closest("[data-sim-step]");
  if (b) {
    const k = b.dataset.stat;
    state.sim[k] = Math.max(0, (state.sim[k] || 0) + +b.dataset.simStep);
    const input = $(`[data-sim-input="${CSS.escape(k)}"]`);
    if (input) input.value = state.sim[k];
    updateSimTotal();
  }
  if (e.target.closest("[data-sim-reset]")) { state.sim = {}; rerender(); }
});
document.addEventListener("input", e => {
  if (e.target.matches("[data-sim-input]")) {
    state.sim[e.target.dataset.simInput] = Math.max(0, parseInt(e.target.value, 10) || 0);
    updateSimTotal();
  }
  if (e.target.matches("#pancake-range")) { state.pancakes = +e.target.value; updateIhop(); }
  if (e.target.matches("#bylaw-search")) { state.bylawQuery = e.target.value; renderBylawList(); }
});

function rulesIhop() {
  return `
    <div class="ihop">
      <div class="card">
        ${cardHead("The 24-Hour IHOP Challenge", "The penalty for finishing last")}
        <div class="card-pad" style="color:var(--text-2);display:flex;flex-direction:column;gap:12px">
          <p style="margin:0">The last-place manager must spend <b style="color:var(--text)">24 continuous hours</b> inside an IHOP. Every pancake eaten takes <b style="color:var(--text)">one hour</b> off the sentence.</p>
          <p style="margin:0">Refusing to serve the sentence means relegation, and an entry on the Wall of Shame.</p>
          <label for="pancake-range" class="stat-label" style="margin-top:12px">Pancakes eaten: <span id="pancake-val" style="color:var(--text)">${state.pancakes}</span></label>
          <input id="pancake-range" type="range" min="0" max="24" step="1" value="${state.pancakes}">
          <div style="display:flex;justify-content:space-between;font-size:12px" class="dim"><span>0</span><span>12</span><span>24</span></div>
          <button class="link-btn" data-go="history" data-sub="shame" style="align-self:flex-start">See the Wall of Shame ${ICON.arrow}</button>
        </div>
      </div>
      <div class="card ihop-visual">
        <div class="ring">
          <svg viewBox="0 0 120 120"><circle cx="60" cy="60" r="52" stroke="var(--surface-3)" stroke-width="10" fill="none"/>
            <circle id="ihop-arc" cx="60" cy="60" r="52" stroke="var(--accent)" stroke-width="10" fill="none" stroke-linecap="round" stroke-dasharray="${2 * Math.PI * 52}" stroke-dashoffset="0" style="transition:stroke-dashoffset .3s"/></svg>
          <div class="ring-center"><div><b class="num" id="ihop-hours">24</b><small>hours left</small></div></div>
        </div>
        <div><div class="pancakes" id="pancake-stack"></div><div class="plate"></div></div>
      </div>
    </div>`;
}
afterRender.rules = () => { if ((state.sub.rules || "prizes") === "ihop") updateIhop(); if (state.sub.rules === "bylaws") renderBylawList(); };

function updateIhop() {
  const n = state.pancakes, left = Math.max(0, 24 - n);
  const C = 2 * Math.PI * 52;
  $("#pancake-val") && ($("#pancake-val").textContent = n);
  $("#ihop-hours") && ($("#ihop-hours").textContent = left);
  $("#ihop-arc") && $("#ihop-arc").setAttribute("stroke-dashoffset", String(C * (1 - left / 24)));
  const stack = $("#pancake-stack");
  if (stack) {
    const cur = stack.children.length;
    if (n > cur) for (let i = cur; i < n; i++) stack.insertAdjacentHTML("beforeend", `<span class="pancake"></span>`);
    else while (stack.children.length > n) stack.lastElementChild.remove();
  }
}

function rulesBylaws() {
  return `
    <div class="toolbar"><label class="search-field">${ICON.search}<input id="bylaw-search" type="search" placeholder="Search the constitution…" value="${esc(state.bylawQuery)}" aria-label="Search the constitution"></label>
      <span class="dim" style="font-size:13px" id="bylaw-count"></span></div>
    <div class="accordion" id="bylaw-list"></div>`;
}

function highlight(text, q) {
  const safe = esc(text);
  if (!q) return safe;
  const re = new RegExp("(" + esc(q).replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + ")", "gi");
  return safe.replace(re, "<mark>$1</mark>");
}

function renderBylawList() {
  const list = $("#bylaw-list");
  if (!list) return;
  const q = state.bylawQuery.trim().toLowerCase();
  let matches = 0;
  list.innerHTML = D.bylaws.map((a, i) => {
    const secs = a.sections.filter(s => !q || (a.title + s.subtitle + s.content).toLowerCase().includes(q));
    if (!secs.length) return "";
    matches += secs.length;
    return `<div class="card acc-item ${q || i === 0 ? "open" : ""}">
      <button class="acc-btn" data-acc aria-expanded="${!!(q || i === 0)}"><span class="art">${esc(a.article)}</span><span class="ttl">${highlight(a.title, q)}</span>${ICON.chevron}</button>
      <div class="acc-panel">${secs.map(s => `<div class="acc-sec"><h5>${highlight(s.subtitle, q)}</h5><p>${highlight(s.content, q)}</p></div>`).join("")}</div>
    </div>`;
  }).join("") || `<div class="empty">Nothing in the constitution matches “${esc(state.bylawQuery)}”.</div>`;
  $("#bylaw-count").textContent = q ? `${matches} section${matches === 1 ? "" : "s"} match` : `${D.bylaws.length} articles`;
}

document.addEventListener("click", e => {
  const b = e.target.closest("[data-acc]");
  if (!b) return;
  const item = b.closest(".acc-item");
  item.classList.toggle("open");
  b.setAttribute("aria-expanded", item.classList.contains("open"));
});

/* ==========================================================================
   Overlays, search, tooltip, theme
   ========================================================================== */

let lastFocus = null;
function openOverlay(sel) {
  lastFocus = document.activeElement;
  const o = $(sel);
  o.classList.add("open");
  document.body.style.overflow = "hidden";
  const f = $("input, button", o);
  f && f.focus();
}
function closeOverlays() {
  $$(".overlay.open").forEach(o => o.classList.remove("open"));
  document.body.style.overflow = "";
  lastFocus && lastFocus.focus && lastFocus.focus();
}
$$(".overlay").forEach(o => o.addEventListener("click", e => { if (e.target === o || e.target.closest("[data-close]")) closeOverlays(); }));

// Command palette
let searchIdx = 0, searchItems = [];
function searchCandidates(q) {
  q = q.trim().toLowerCase();
  const mgrs = Object.values(managerById).filter(m => !q || [m.name, m.teamName, m.city, m.shortName].join(" ").toLowerCase().includes(q))
    .map(m => ({ type: "mgr", id: m.id, html: `${crest(m, "sm")}<span class="club-text"><span class="club-name">${esc(m.teamName)}</span><span class="club-mgr">${esc(m.name)} · ${esc(m.city)}</span></span>`, kind: standingById[m.id] ? ordinal(standingById[m.id].rank) : "" }));
  const pages = PAGES.filter(p => !q || p.label.toLowerCase().includes(q))
    .map(p => ({ type: "page", id: p.id, html: `<span class="crest sm" style="--c:#3a4656">${esc(p.label[0])}</span><span class="club-name">${esc(p.label)}</span>`, kind: "Page" }));
  return { mgrs, pages };
}
function renderSearch() {
  const { mgrs, pages } = searchCandidates($("#search-input").value);
  searchItems = [...mgrs, ...pages];
  searchIdx = Math.min(searchIdx, Math.max(0, searchItems.length - 1));
  let i = 0;
  const row = it => `<button class="palette-item" role="option" data-idx="${i}" aria-selected="${i++ === searchIdx}">${it.html}<span class="kind">${esc(it.kind)}</span></button>`;
  $("#search-results").innerHTML =
    (mgrs.length ? `<div class="palette-group">Clubs</div>${mgrs.map(row).join("")}` : "") +
    (pages.length ? `<div class="palette-group">Pages</div>${pages.map(row).join("")}` : "") ||
    `<div class="empty" style="margin:8px">No matches</div>`;
}
function chooseSearch(idx) {
  const it = searchItems[idx];
  if (!it) return;
  closeOverlays();
  if (it.type === "mgr") openManager(it.id); else go(it.id);
}
function openSearch() { $("#search-input").value = ""; searchIdx = 0; renderSearch(); openOverlay("#search-overlay"); }
$("#open-search").addEventListener("click", openSearch);
$("#search-input").addEventListener("input", () => { searchIdx = 0; renderSearch(); });
$("#search-results").addEventListener("click", e => { const b = e.target.closest("[data-idx]"); if (b) chooseSearch(+b.dataset.idx); });
$("#search-input").addEventListener("keydown", e => {
  if (e.key === "ArrowDown" || e.key === "ArrowUp") {
    e.preventDefault();
    searchIdx = (searchIdx + (e.key === "ArrowDown" ? 1 : -1) + searchItems.length) % Math.max(1, searchItems.length);
    renderSearch();
    $(`[data-idx="${searchIdx}"]`)?.scrollIntoView({ block: "nearest" });
  } else if (e.key === "Enter") { e.preventDefault(); chooseSearch(searchIdx); }
});

document.addEventListener("keydown", e => {
  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") { e.preventDefault(); openSearch(); }
  else if (e.key === "Escape") closeOverlays();
  else if (e.key === "/" && !/input|textarea/i.test(document.activeElement.tagName)) { e.preventDefault(); openSearch(); }
});

// Tooltip
const tip = $("#tooltip");
document.addEventListener("mouseover", e => {
  const t = e.target.closest("[data-tip]");
  if (!t) { tip.classList.remove("show"); return; }
  tip.innerHTML = t.dataset.tip;
  tip.classList.add("show");
});
document.addEventListener("mousemove", e => {
  if (!tip.classList.contains("show")) return;
  const pad = 14, r = tip.getBoundingClientRect();
  let x = e.clientX + pad, y = e.clientY + pad;
  if (x + r.width > innerWidth - 8) x = e.clientX - r.width - pad;
  if (y + r.height > innerHeight - 8) y = e.clientY - r.height - pad;
  tip.style.left = x + "px"; tip.style.top = y + "px";
});
document.addEventListener("scroll", () => tip.classList.remove("show"), { passive: true });

// Theme
function effectiveTheme() {
  return document.documentElement.dataset.theme || (matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark");
}
function paintThemeIcon() { $("#theme-toggle").innerHTML = effectiveTheme() === "dark" ? ICON.sun : ICON.moon; }
$("#theme-toggle").addEventListener("click", () => {
  const next = effectiveTheme() === "dark" ? "light" : "dark";
  document.documentElement.dataset.theme = next;
  try { localStorage.setItem("gi-theme", next); } catch (e) {}
  paintThemeIcon();
});

/* ---------- Boot ---------- */
$("#footer-league").textContent = D.metadata.leagueId;
if (CS.syncedAt) {
  $("#footer-synced").textContent = ` · Updated ${new Date(CS.syncedAt).toLocaleString("en-US", { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" })}`;
}

// A tab left open reloads itself when the hub rolls over to the next gameweek.
const nextRollover = rolloverAt(currentGw);
if (nextRollover !== null && nextRollover > Date.now()) {
  setTimeout(() => location.reload(), Math.min(nextRollover - Date.now() + 1000, 2147483647));
}
window.addEventListener("hashchange", () => { parseHash(); render(); });
paintThemeIcon();
parseHash();
render();
